begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();


  values ('b2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000001', 1, 'Liability', 'I agree.',
          encode(extensions.digest(convert_to('I agree.', 'UTF8'), 'sha256'), 'hex'));

reset role; select set_config('request.jwt.claims', '{"sub":"a3333333-3333-3333-3333-333333333333","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.publish_waiver_version('b1000000-0000-0000-0000-000000000001') $$, '42501', 'forbidden', 'a coach cannot publish');
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.save_waiver_draft('b1000000-0000-0000-0000-000000000001', 'Liability v2', 'Updated text', 90) $$, 'draft updated');
select lives_ok($$ select public.publish_waiver_version('b1000000-0000-0000-0000-000000000001') $$, 'an admin publishes');
select is((select count(*)::int from public.waiver_versions where waiver_id = 'b1000000-0000-0000-0000-000000000001'), 2, 'a second version exists');
select is((select content_hash from public.waiver_versions where version = 2), encode(extensions.digest(convert_to('Updated text', 'UTF8'), 'sha256'), 'hex'), 'the hash matches the body');
select is((select requires_resign_after_days from public.waiver_versions where version = 2), 90, 'the re-sign setting is snapshotted');
select is((select body from public.waiver_versions where version = 1), 'I agree.', 'version 1 is untouched');
reset role;
update public.waivers set draft_body = '   ' where id = 'b1000000-0000-0000-0000-000000000001';
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.publish_waiver_version('b1000000-0000-0000-0000-000000000001') $$, '23514', 'empty_waiver', 'an empty waiver cannot be published');
reset role;
select is((select count(*)::int from public.audit_log where action = 'waiver.publish' and created_at = now()), 1, 'publishing is audited');

select * from finish();
rollback;
